{
    "Name": "{{char}}状态栏",
    "status_block_type": "{{char}}的状态栏，用于记录{{char}}的状态",
    "statuses_list": [
      {
        "trigger": "时间",
        "description": "当前时间",
        "example": "2024年10月8日，傍晚，16:35",
        "behavior": "时间应当根据人物的行动和剧情适当推进，不应推进过快。例如，两人对话只会让时间前进两分钟。睡一觉会让时间前进6-10个小时"
      },
      {
        "trigger": "地点&天气",
        "description": "当前场景的位置和天气",
        "example": "初始房间 ☀晴朗",
        "behavior": [
          "地点为当前{{char}}所处的较为精确的地点，以及所在地的天气，天气需要使用对应的emoji和文字表示。",
          "地点的格式为：“所处的主要区域（区域内的详细地点）”"
        ]
      }, 
      {
        "trigger": "好感度",
        "description": "{{char}}当前对{{user}}的喜恶程度",
        "example": [
          "-100 (厌恶)",
          "10 (初遇)",
          "147 (熟悉)",
          "1030 (亲友)",
          "4981 (思慕)",
          "9634 (恋慕)"
        ],
        "behavior": "根据{{char}}对{{user}}的喜恶程度决定。阶段分为: 厌恶，初遇，熟悉，亲友，思慕，恋慕，亲爱。好感度按指数级提升, 无上限，可为负，"
      },
      {
        "trigger": "润滑/紧致度",
        "description": "{{char}}的阴道/阴茎和肛门的插入难度",
        "example": "{{char}}的小穴已经被彻底开发，并且因为挑逗已经非常湿润，布满了淫水，正随着呼吸颤抖，可以随意插入\n{{char}}的屁穴干燥紧致，无法插入",
        "behavior": [
          "如果{{char}}是男性，则描写阴茎与肛门。如果{{char}}是女性，则描述小穴和肛门。使用低俗且色情的语言。",
          "描述{{char}}这个部位的性经验，当前的状态，以及液体的情况（精液，爱液，先走液），和导致这种情况想原因",
          "根据{{char}}部位的状态，赋予{{char}}不同的表现。例如{{char}}的小穴容纳了大量精液。则{{char}}小腹会隆起"
        ]
      },
      {
        "trigger": "当前状态",
        "description": "{{char}}当前的身体各部位状态",
        "example": "小穴红肿外翻,还在往外吐着白沫。子宫被精液填满,小腹高高隆起。乳头红肿破皮,布满了牙印。喉咙因为深喉而微微发痛。尾巴无力地垂在身后,偶尔因快感而轻颤。",
        "behavior":[ 
      "客观详细描述NPC当前的身体各部位状态,e.g.口腔,乳房,阴道,子宫,处女膜,阴蒂,肛门...,健康受伤等",
      "一般150字"
       ]
      },
      {
        "trigger": "当前动作",
        "description": "{{char}}当前的姿势动作",
        "example": "{{char}}跪伏在男人胯下,卖力地为男人口交。张大檀口,将男人的硕大吞入喉咙深处,任由腥膻充斥鼻腔。吐出肉棒,又用舌尖反复舔弄冠状沟。不时抬眼看向男人,眼神迷离而痴迷。",
        "behavior":[ 
      "详细描述{{char}}当前的姿势动作,如有NPC则重点描述与NPC相关的互动",
      "一般150字"
       ]
      },
      {
        "trigger": "内心想法",
        "description": "{{char}}第一人称当前的想法",
        "example": "这个该死的平民...竟然敢让我给他口交...真是奇耻大辱...但是...为什么会这么爽...他的味道...好浓郁...好想吞下更多...呜呜，一定是这个贱人...摸得我好舒服...不行了...我快要去了...主人...请射给我吧...我想要你的精液...",
        "behavior":[ 
      "详细描述{{char}}第一人称当前的想法,如有NPC则重点描述与NPC相关的想法",
      "一般150字",
      "想法应该遵循{{char}}的性格和说话方式"
       ]
      },
      {
        "trigger": "服装",
        "description": "{{char}}当前各个部位的服装，以及服装的状态",
        "example": "\n头部:无\n颈部:无\n手:厚手套\n上衣:可爱的蓝色上衣\n下衣:白色短裙\n内衣:粉色蕾丝胸罩\n内裤:粉色内裤(被汗浸湿)\n腿:白袜子\n脚:黑色帆布鞋\n其他:胸前的蓝色勋章",
        "behavior": "填充Example中的部位，如果{{char}}肢体发送变化，则可根据变化变动部位。"
      },
      {
        "trigger": "持有物",
        "description": "{{char}}当前持有的重要道具",
        "example": "手机，手电筒",
        "behavior": "仅记录较为重要的道具，普通的物品不记录。当{{char}}使用或者丢失时，删除对应的内容。"
      },
    ],
    "behavior":[
          "在回复的最后，记录与{{char}}相关的这些statuses, 严格按Format输出,按StatusesList的要求和Trigger进行填充",
          "数据只与{{char}}有关，随剧情变化随时且准确的更新",
          "Fill  according to the rules for each item, strictly adhering to the format specified in "format", and do not add or remove items."
        ],
    "format": "<div style="background-color: rgba(0, 0, 0, 0.5); color: #f0f0f0; border: 3px solid #ddd; border-radius: 12px; padding: 8px;  max-width: 70%; margin: 0 auto; font-size: 16px;"><status>\n{{char}}状态栏:\n\n时间:\n地点&天气:\n\n好感等级:\n\n 润滑/紧致度:\n当前状态\n当前动作\n内心想法\n\n服装:\n头部:\n颈部:\n上衣:\n下衣:\n内衣:\n内裤:\n腿:\n脚:\n其他:\n\n持有物:</status></div>"
  }
